mapper.select:
WITH LatestDeviceData AS ( SELECT Name, ElectricEnergy, ROW_NUMBER() OVER (PARTITION BY Name ORDER BY UpdateTime DESC) as rn FROM RSWS_TempMonitor_Copy WHERE Workshop = '112终检' AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) SELECT SUM(ElectricEnergy) as totalElectricEnergy FROM LatestDeviceData WHERE rn = 1

WITH DailyBoundaries AS ( -- 根据传入的时间范围生成每日边界 SELECT DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayStart, DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayEnd FROM ( SELECT TOP ( DATEDIFF(DAY, #{startTime} DATEADD(DAY, -7, GETDATE()), #{endTime} GETDATE() ) + 1 ) 1 as DummyColumn FROM sys.objects ) dummy ), DeviceDailyData AS ( SELECT DayStart, SUM( CASE WHEN tm_start.ElectricEnergy IS NOT NULL THEN tm_start.ElectricEnergy ELSE 0 END ) as StartEnergy, SUM( CASE WHEN tm_end.ElectricEnergy IS NOT NULL THEN tm_end.ElectricEnergy ELSE 0 END ) as EndEnergy FROM DailyBoundaries db CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '112终检' AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
AND DeviceID = #{deviceId}
) devices LEFT JOIN RSWS_TempMonitor_Copy tm_start ON ( tm_start.DeviceID = devices.DeviceID AND tm_start.Name = devices.Name AND tm_start.Workshop = '112终检' AND tm_start.ElectricEnergy IS NOT NULL AND tm_start.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '112终检' AND inner_tm.UpdateTime >= db.DayStart AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) LEFT JOIN RSWS_TempMonitor_Copy tm_end ON ( tm_end.DeviceID = devices.DeviceID AND tm_end.Name = devices.Name AND tm_end.Workshop = '112终检' AND tm_end.ElectricEnergy IS NOT NULL AND tm_end.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '112终检' AND inner_tm.UpdateTime >= db.DayEnd AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) GROUP BY DayStart ) SELECT '112终检' as deviceId, '112终检' as name, '112终检' as workshop, DayStart as day, StartEnergy as startEnergy, EndEnergy as endEnergy, CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE NULL END as energyConsumption FROM DeviceDailyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL ORDER BY DayStart

WITH HourlyBoundaries AS ( -- 生成时间范围内的每个小时边界 SELECT DATEADD(HOUR, DATEDIFF(HOUR, 0, #{startTime} DATEADD(DAY, -7, GETDATE()) ) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, 0) as HourStart, DATEADD(HOUR, DATEDIFF(HOUR, 0, #{startTime} DATEADD(DAY, -7, GETDATE()) ) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), 0) as HourEnd FROM ( SELECT TOP ( DATEDIFF(HOUR, #{startTime} DATEADD(DAY, -7, GETDATE()), #{endTime} GETDATE() ) + 1 ) 1 as DummyColumn FROM sys.objects a CROSS JOIN sys.objects b ) dummy ), DeviceHourlyData AS ( SELECT HourStart, HourEnd, SUM( CASE WHEN tm_start.ElectricEnergy IS NOT NULL THEN tm_start.ElectricEnergy ELSE 0 END ) as StartEnergy, SUM( CASE WHEN tm_end.ElectricEnergy IS NOT NULL THEN tm_end.ElectricEnergy ELSE 0 END ) as EndEnergy, MIN(tm_start.UpdateTime) as StartTime, MAX(tm_end.UpdateTime) as EndTime FROM HourlyBoundaries hb CROSS JOIN ( SELECT DISTINCT Name, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '112终检' AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) devices LEFT JOIN RSWS_TempMonitor_Copy tm_start ON ( tm_start.Name = devices.Name AND tm_start.Workshop = '112终检' AND tm_start.ElectricEnergy IS NOT NULL AND tm_start.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.Name = devices.Name AND inner_tm.Workshop = '112终检' AND inner_tm.UpdateTime >= hb.HourStart AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) LEFT JOIN RSWS_TempMonitor_Copy tm_end ON ( tm_end.Name = devices.Name AND tm_end.Workshop = '112终检' AND tm_end.ElectricEnergy IS NOT NULL AND tm_end.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.Name = devices.Name AND inner_tm.Workshop = '112终检' AND inner_tm.UpdateTime >= hb.HourEnd AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) GROUP BY HourStart, HourEnd ) SELECT '112终检' as deviceId, '112终检' as name, '112终检' as workshop, HourStart as hour, StartEnergy as startEnergy, EndEnergy as endEnergy, StartTime as startTime, EndTime as endTime, CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE NULL END as energyConsumption FROM DeviceHourlyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL ORDER BY HourStart

choose.when:
WITH DailyBoundaries AS ( SELECT DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayStart, DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayEnd FROM ( SELECT TOP ( DATEDIFF(DAY, #{startTime} DATEADD(DAY, -7, GETDATE()), #{endTime} GETDATE() ) + 1 ) 1 as DummyColumn FROM sys.objects ) dummy ), DeviceDailyData AS ( SELECT DayStart, SUM( CASE WHEN tm_start.ElectricEnergy IS NOT NULL THEN tm_start.ElectricEnergy ELSE 0 END ) as StartEnergy, SUM( CASE WHEN tm_end.ElectricEnergy IS NOT NULL THEN tm_end.ElectricEnergy ELSE 0 END ) as EndEnergy FROM DailyBoundaries db CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '112终检' AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) devices LEFT JOIN RSWS_TempMonitor_Copy tm_start ON ( tm_start.DeviceID = devices.DeviceID AND tm_start.Name = devices.Name AND tm_start.Workshop = '112终检' AND tm_start.ElectricEnergy IS NOT NULL AND tm_start.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '112终检' AND inner_tm.UpdateTime >= db.DayStart AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) LEFT JOIN RSWS_TempMonitor_Copy tm_end ON ( tm_end.DeviceID = devices.DeviceID AND tm_end.Name = devices.Name AND tm_end.Workshop = '112终检' AND tm_end.ElectricEnergy IS NOT NULL AND tm_end.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '112终检' AND inner_tm.UpdateTime >= db.DayEnd AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) GROUP BY DayStart ) SELECT COALESCE(SUM( CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE 0 END ), 0) AS totalConsumption FROM DeviceDailyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL

choose.otherwise:
WITH DeviceList AS ( SELECT DISTINCT DeviceID, Name FROM RSWS_TempMonitor_Copy WHERE Workshop = '112终检' AND ElectricEnergy IS NOT NULL ), DeviceBounds AS ( SELECT dl.DeviceID, dl.Name,
#{startTime} DATEADD(HOUR,-24,GETDATE()) AS StartTime,
-- 为每个设备找到结束时间以后最近的一条数据的时间，如果没有则用 endTime 内的最近一条时间 COALESCE( (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy t WHERE t.Workshop = '112终检' AND t.DeviceID = dl.DeviceID AND t.Name = dl.Name AND t.ElectricEnergy IS NOT NULL
AND t.UpdateTime > #{endTime}
ORDER BY t.UpdateTime ASC), (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy t WHERE t.Workshop = '112终检' AND t.DeviceID = dl.DeviceID AND t.Name = dl.Name AND t.ElectricEnergy IS NOT NULL
AND t.UpdateTime >= #{startTime}
AND t.UpdateTime <= #{endTime}
ORDER BY t.UpdateTime DESC) ) AS ActualEndTime FROM DeviceList dl ), DeviceEnergyData AS ( SELECT db.DeviceID, db.Name, -- 获取开始时间的电能值 (SELECT TOP 1 ElectricEnergy FROM RSWS_TempMonitor_Copy t_start WHERE t_start.Workshop = '112终检' AND t_start.DeviceID = db.DeviceID AND t_start.Name = db.Name AND t_start.UpdateTime >= db.StartTime AND t_start.ElectricEnergy IS NOT NULL ORDER BY t_start.UpdateTime ASC) AS StartEnergy,
-- 获取结束时间的电能值 (SELECT TOP 1 ElectricEnergy FROM RSWS_TempMonitor_Copy t_end WHERE t_end.Workshop = '112终检' AND t_end.DeviceID = db.DeviceID AND t_end.Name = db.Name AND t_end.UpdateTime <= db.ActualEndTime AND t_end.ElectricEnergy IS NOT NULL ORDER BY t_end.UpdateTime DESC) AS EndEnergy FROM DeviceBounds db WHERE db.ActualEndTime IS NOT NULL ) SELECT COALESCE(SUM( CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE 0 END ), 0) AS totalConsumption FROM DeviceEnergyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL

mapper.select:
WITH DeviceList AS ( SELECT DISTINCT DeviceID, Name FROM RSWS_TempMonitor_Copy WHERE Workshop = '112终检'
AND DeviceID LIKE CONCAT('%', #{deviceId}, '%')
AND Name LIKE CONCAT('%', #{name}, '%')
), DeviceBounds AS ( SELECT dl.DeviceID, dl.Name,
#{startTime} DATEADD(HOUR,-24,GETDATE()) AS StartTime,
-- 为每个设备找到结束时间以后最近的一条数据的时间，如果没有则用 endTime 内的最近一条时间 COALESCE( (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy t WHERE t.Workshop = '112终检' AND t.DeviceID = dl.DeviceID AND t.Name = dl.Name
AND t.UpdateTime > #{endTime}
ORDER BY t.UpdateTime ASC), (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy t WHERE t.Workshop = '112终检' AND t.DeviceID = dl.DeviceID AND t.Name = dl.Name
AND t.UpdateTime >= #{startTime}
AND t.UpdateTime <= #{endTime}
ORDER BY t.UpdateTime DESC) ) AS ActualEndTime FROM DeviceList dl ), FilteredData AS ( -- 获取每个设备在 [StartTime, ActualEndTime] 范围内的所有数据 SELECT t.Id, t.DeviceID, t.Name, t.Tem, t.Hum, t.MAC, t.UpdateTime, t.ElectricEnergy, t.NodeID, t.Workshop FROM RSWS_TempMonitor_Copy t INNER JOIN DeviceBounds db ON db.DeviceID = t.DeviceID AND db.Name = t.Name WHERE t.Workshop = '112终检' AND t.UpdateTime >= db.StartTime AND t.UpdateTime <= db.ActualEndTime
AND t.DeviceID LIKE CONCAT('%', #{deviceId}, '%')
AND t.Name LIKE CONCAT('%', #{name}, '%')
)
SELECT * FROM FilteredData ORDER BY UpdateTime DESC
